#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Fused BN (inference) + dual AvgPool3d(2) == single AvgPool3d(4) kernel.
// Each thread computes one output voxel by averaging 4x4x4=64 input values,
// then applying BN affine: out = weight[c]*(mean64 - running_mean[c])/sqrt(running_var[c]+eps) + bias[c]
__global__ void fused_bn_pool_kernel(
    const float* __restrict__ input,   // [N, C, D, H, W]
    float* __restrict__ output,        // [N, C, D4, H4, W4]
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    float eps,
    int N, int C, int D, int H, int W,
    int D4, int H4, int W4)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * D4 * H4 * W4;
    if (idx >= total) return;

    // decode output index
    int w4 = idx % W4; int tmp = idx / W4;
    int h4 = tmp % H4; tmp /= H4;
    int d4 = tmp % D4; tmp /= D4;
    int c  = tmp % C;  tmp /= C;
    int n  = tmp;

    // base input coords
    int d0 = d4 * 4, h0 = h4 * 4, w0 = w4 * 4;
    int HW = H * W;
    int DHW = D * HW;
    int CDHW = C * DHW;

    float sum = 0.0f;
    int base = n * CDHW + c * DHW;
    #pragma unroll
    for (int dd = 0; dd < 4; ++dd) {
        int di = (d0 + dd) * HW;
        #pragma unroll
        for (int dh = 0; dh < 4; ++dh) {
            int hi = (h0 + dh) * W;
            #pragma unroll
            for (int dw = 0; dw < 4; ++dw) {
                sum += __ldg(&input[base + di + hi + w0 + dw]);
            }
        }
    }
    float mean64 = sum * (1.0f / 64.0f);

    // BN affine (inference)
    float m = __ldg(&bn_mean[c]);
    float v = __ldg(&bn_var[c]);
    float w = __ldg(&bn_weight[c]);
    float b = __ldg(&bn_bias[c]);
    float inv_std = rsqrtf(v + eps);
    output[idx] = w * (mean64 - m) * inv_std + b;
}

// Two-pass fused: pass1 computes per-channel mean/var over (N,D,H,W),
// pass2 applies affine + 4x4x4 pooling.
__global__ void fused_bn_train_pass1(
    const float* __restrict__ input,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    int N, int C, int D, int H, int W)
{
    int c = blockIdx.x;
    int spatial = N * D * H * W;
    float sum = 0.0f, sum2 = 0.0f;
    int CDHW = C * D * H * W;
    int DHW = D * H * W;
    for (int i = threadIdx.x; i < spatial; i += blockDim.x) {
        int n = i / DHW;
        int dhw = i % DHW;
        float val = __ldg(&input[n * C * DHW + c * DHW + dhw]);
        sum  += val;
        sum2 += val * val;
    }
    // block reduce
    __shared__ float s_sum[256], s_sum2[256];
    s_sum[threadIdx.x]  = sum;
    s_sum2[threadIdx.x] = sum2;
    __syncthreads();
    for (int stride = blockDim.x/2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x]  += s_sum[threadIdx.x + stride];
            s_sum2[threadIdx.x] += s_sum2[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        float m = s_sum[0] / (float)spatial;
        float v = s_sum2[0] / (float)spatial - m * m;
        mean_out[c] = m;
        var_out[c]  = v;
    }
}

__global__ void fused_bn_train_pass2(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ mean_buf,
    const float* __restrict__ var_buf,
    float eps,
    int N, int C, int D, int H, int W,
    int D4, int H4, int W4)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * D4 * H4 * W4;
    if (idx >= total) return;

    int w4 = idx % W4; int tmp = idx / W4;
    int h4 = tmp % H4; tmp /= H4;
    int d4 = tmp % D4; tmp /= D4;
    int c  = tmp % C;  tmp /= C;
    int n  = tmp;

    int d0 = d4 * 4, h0 = h4 * 4, w0 = w4 * 4;
    int HW = H * W, DHW = D * HW;
    int base = n * C * DHW + c * DHW;

    float sum = 0.0f;
    #pragma unroll
    for (int dd = 0; dd < 4; ++dd) {
        int di = (d0 + dd) * HW;
        #pragma unroll
        for (int dh = 0; dh < 4; ++dh) {
            int hi = (h0 + dh) * W;
