torch::Tensor fused_bn_avgpool3d(
    torch::Tensor input,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor bn_running_mean,
    torch::Tensor bn_running_var,
    double eps,
    bool training,
    double momentum)
