        int total = N * C * D4 * H4 * W4;
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        fused_bn_pool_kernel<<<blocks, threads, 0, stream>>>(
            input.data_ptr<float>(), output.data_ptr<float>(),
            bn_weight.data_ptr<float>(), bn_bias.data_ptr<float>(),
            bn_running_mean.data_ptr<float>(), bn_running_var.data_ptr<float>(),
            (float)eps, N, C, D, H, W, D4, H4, W4);
    } else {
        // training: compute per-channel mean/var, update running stats, then fuse affine+pool
        auto mean_buf = torch::empty({C}, input.options());
        auto var_buf  = torch::empty({C}, input.options());
        int threads1 = 256;
        fused_bn_train_pass1<<<C, threads1, 0, stream>>>(
            input.data_ptr<float>(),
            mean_buf.data_ptr<float>(), var_buf.data_ptr<float>(),
            N, C, D, H, W);
