        float unbiased_scale = (float)spatial / (float)(spatial - 1);
        bn_running_var.mul_(1.0 - momentum).add_(var_buf * (momentum * unbiased_scale));

        int total = N * C * D4 * H4 * W4;
        int threads2 = 256;
        int blocks2 = (total + threads2 - 1) / threads2;
        fused_bn_train_pass2<<<blocks2, threads2, 0, stream>>>(
            input.data_ptr<float>(), output.data_ptr<float>(),
            bn_weight.data_ptr<float>(), bn_bias.data_ptr<float>(),
            mean_buf.data_ptr<float>(), var_buf.data_ptr<float>(),
            (float)eps, N, C, D, H, W, D4, H4, W4);
    }
